it('Full inline-image split-Text history restores the authored collapsed caret', async ({ task }) => {
  vi.useFakeTimers();
  const imageMarkdown = '![pic](image.png)';
  const codeHtml = fullOwnerCodeBlock('protected\n', 'b1');
  const base: FullOwnerAcceptedDocument = {
    // Formal own-node extents leave the blank separator at line 1 unmapped.
    editMap: fullOwnerEditMap('inline-image-split-text-history', [
      { id: 'b0', startLine: 0, endLine: 1 },
      { id: 'b1', startLine: 2, endLine: 5 }
    ]),
    html: fullOwnerBlock('<p>alpha<img src="image.png" alt="pic">tail</p>', 'b0') + codeHtml,
    markdown: `alpha${imageMarkdown}tail\n\n\`\`\`js\nprotected\n\`\`\``
  };
  const changed: FullOwnerAcceptedDocument = {
    ...base,
    html: fullOwnerBlock('<p>alQpha<img src="image.png" alt="pic">tail</p>', 'b0') + codeHtml,
    markdown: `alQpha${imageMarkdown}tail\n\n\`\`\`js\nprotected\n\`\`\``
  };
  const fixture = createFullOwnerFixture({
    ...base, signature: 'inline-image-split-text-history-initial', sourceCaret: 0
  });
  const applyTextChange = vi.spyOn(fixture.history, 'applyTextChange');
  const undo = vi.spyOn(fixture.history, 'undo');
  const redo = vi.spyOn(fixture.history, 'redo');
  const receipt = {
    phase: 'setup', classification: 'SETUP_PENDING', prevented: null as boolean | null,
    firstDivergence: null as string | null, mismatches: 0,
    writes: [] as unknown[], commands: { undo: [] as unknown[], redo: [] as unknown[] },
    snapshots: [] as unknown[]
  };
  Object.assign(task.meta, { inlineImageSplitTextHistory: receipt });
  const nativePoint = () => {
    const paragraph = fixture.surface.querySelector('p');
    const native = window.getSelection();
    if (!(paragraph instanceof HTMLParagraphElement) || !native) {
      throw new Error('inline-image-history-native-paragraph-missing');
    }
    const offset = (node: Node | null, localOffset: number): number => {
      if (!node || !paragraph.contains(node)) {
        throw new Error('inline-image-history-native-point-outside-paragraph');
      }
      const prefix = document.createRange();
      prefix.selectNodeContents(paragraph);
      prefix.setEnd(node, localOffset);
      return prefix.toString().length;
    };
    return {
      anchor: offset(native.anchorNode, native.anchorOffset),
      focus: offset(native.focusNode, native.focusOffset),
      collapsed: native.isCollapsed, focused: document.activeElement === fixture.surface,
      anchorNodeName: native.anchorNode?.nodeName, anchorLocalOffset: native.anchorOffset
    };
  };
  const recordMismatch = (boundary: string, matches: boolean): void => {
    if (matches) return;
    receipt.mismatches += 1;
    receipt.firstDivergence ??= boundary;
  };
  try {
    expect(fixture.runtime().isEditable()).toBe(true);
    expect(fixture.history.getValue()).toBe(base.markdown);
    expect(serializeVisualMarkdown(fixture.surface)).toBe(base.markdown);
    expect(fixture.history.getHistoryState()).toEqual({ undoDepth: 0, redoDepth: 0 });
    const paragraph = fixture.surface.querySelector('p');
    const alpha = paragraph?.firstChild;
    const image = paragraph?.childNodes[1];
    const tail = paragraph?.childNodes[2];
    const protectedPre = fixture.surface.querySelector('pre');
    if (!(paragraph instanceof HTMLParagraphElement) || !(alpha instanceof Text)
      || !(image instanceof HTMLImageElement) || !(tail instanceof Text)) {
      throw new Error('inline-image-history-formal-paragraph-shape-invalid');
    }
    expect(paragraph.childNodes).toHaveLength(3);
    expect(alpha.data).toBe('alpha');
    expect(image.getAttribute('src')).toBe('image.png');
    expect(image.getAttribute('alt')).toBe('pic');
    expect(tail.data).toBe('tail');
    expect(protectedPre).toBeInstanceOf(HTMLPreElement);
    fixture.surface.focus();
    const htmlBeforeSplit = fixture.surface.innerHTML;
    const textBeforeSplit = fixture.surface.textContent;
    const pha = alpha.splitText(2);
    expect(Array.from(paragraph.childNodes)).toEqual([alpha, pha, image, tail]);
    expect(alpha.data).toBe('al');
    expect(pha.data).toBe('pha');
    expect(fixture.surface.innerHTML).toBe(htmlBeforeSplit);
    expect(fixture.surface.textContent).toBe(textBeforeSplit);
    placeCaretInText(pha, 0);
    expect(nativePoint()).toMatchObject({ anchor: 2, focus: 2, collapsed: true, focused: true });
    expect(fixture.history.getSelection()).toEqual({ direction: 'none', start: 0, end: 0 });
    expect(fixture.onFailure).not.toHaveBeenCalled();
    expect(fixture.onTransferFailure).not.toHaveBeenCalled();
    receipt.phase = 'native-insertion';
    act(() => {
      receipt.prevented = fullOwnerNativeInsert(fixture.surface, pha, 0, 'Q', 'insertText', true).prevented;
    });
    await act(async () => { vi.advanceTimersByTime(90); await Promise.resolve(); });
    expect(fixture.history.getValue()).toBe(changed.markdown);
    expect(fixture.history.getSelection()).toEqual({ direction: 'none', start: 3, end: 3 });
    expect(fixture.history.getHistoryState()).toEqual({ undoDepth: 1, redoDepth: 0 });
    expect(paragraph.textContent).toBe('alQphatail');
    expect(paragraph.querySelector('img')).toBe(image);
    expect(fixture.surface.querySelector('pre')).toBe(protectedPre);
    expect(fixture.onFailure).not.toHaveBeenCalled();
    expect(fixture.onTransferFailure).not.toHaveBeenCalled();
    expect(applyTextChange.mock.calls).toHaveLength(1);
    expect(applyTextChange.mock.calls[0]?.[0]).toMatchObject({
      historySelectionBefore: { direction: 'none', start: 2, end: 2 },
      recordHistorySelection: true,
      selection: { direction: 'none', start: 3, end: 3 },
      value: changed.markdown
    });
    receipt.classification = 'VALID_NATIVE_COMMIT';
    receipt.snapshots.push({ phase: 'inserted', value: fixture.history.getValue(),
      selection: fixture.history.getSelection(), native: nativePoint() });
    if (fixture.runtime().isTransferPending()) act(() => fixture.accept(changed));

    for (const isRedo of [false, true]) {
      receipt.phase = isRedo ? 'redo' : 'undo';
      act(() => fullOwnerHistoryKey(fixture.surface, isRedo));
      const expectedDocument = isRedo ? changed : base;
      const expectedOffset = isRedo ? 3 : 2;
      const value = fixture.history.getValue();
      const selection = fixture.history.getSelection();
      recordMismatch(`${receipt.phase}: source`, value === expectedDocument.markdown);
      expect.soft(value, `${receipt.phase}: exact canonical source`).toBe(expectedDocument.markdown);
      recordMismatch(`${receipt.phase}: canonical caret`, selection.direction === 'none'
        && selection.start === expectedOffset && selection.end === expectedOffset);
      expect.soft(selection, `${receipt.phase}: authored canonical caret`).toEqual({
        direction: 'none', start: expectedOffset, end: expectedOffset
      });
      if (fixture.runtime().isTransferPending() && value === expectedDocument.markdown) {
        act(() => fixture.accept(expectedDocument));
      }
      await act(async () => { vi.advanceTimersByTime(0); await Promise.resolve(); });
      const native = nativePoint();
      recordMismatch(`${receipt.phase}: native caret`, native.anchor === expectedOffset
        && native.focus === expectedOffset && native.collapsed && native.focused);
      // A resolvable old child index may name IMG@0, whose semantic paragraph
      // offset is 5, not the authored alpha@2. Node existence is not identity.
      expect.soft(native, `${receipt.phase}: authored native text position`).toMatchObject({
        anchor: expectedOffset, focus: expectedOffset, collapsed: true, focused: true
      });
      receipt.snapshots.push({ phase: receipt.phase, value, selection, native,
        history: fixture.history.getHistoryState(),
        failures: fixture.onFailure.mock.calls.map(([code]) => code),
        transferFailures: fixture.onTransferFailure.mock.calls.length });
      expect.soft(fixture.history.getHistoryState()).toEqual({
        undoDepth: isRedo ? 1 : 0, redoDepth: isRedo ? 0 : 1
      });
      expect.soft(fixture.surface.querySelector('img')?.getAttribute('src')).toBe('image.png');
      expect.soft(fixture.surface.querySelector('img')?.getAttribute('alt')).toBe('pic');
      expect.soft(fixture.surface.querySelector('pre code')?.textContent).toBe('protected\n');
      expect.soft(fixture.runtime().isEditable()).toBe(true);
      expect.soft(fixture.onFailure).not.toHaveBeenCalled();
      expect.soft(fixture.onTransferFailure).not.toHaveBeenCalled();
    }
    receipt.phase = 'complete';
    receipt.classification = receipt.mismatches ? 'RED_NATIVE_HISTORY' : 'GREEN_CONTROL';
  } catch (error) {
    receipt.classification = receipt.phase === 'setup' ? 'SETUP_FAILURE'
      : receipt.classification === 'VALID_NATIVE_COMMIT' ? 'CONSUMER_BOUNDARY_FAILURE' : 'INVERSE_PREREQUISITE_FAILURE';
    throw error;
  } finally {
    receipt.writes = applyTextChange.mock.calls.map(([change], index) => ({
      change, result: { type: applyTextChange.mock.results[index]?.type,
        value: applyTextChange.mock.results[index]?.value ?? null }
    }));
    receipt.commands = {
      undo: undo.mock.results.map((result) => ({ type: result.type, value: result.value })),
      redo: redo.mock.results.map((result) => ({ type: result.type, value: result.value }))
    };
    applyTextChange.mockRestore(); undo.mockRestore(); redo.mockRestore();
    fixture.unmount(); vi.useRealTimers();
  }
});

describe('Full owned-gap sequential native deletion consumers', () => {
  const scenarios = (['literal prefix', 'created fence'] as const).flatMap((transition) =>
    (['top', 'middle', 'tail'] as const).flatMap((position) =>
      (['~~~', '```'] as const).map((family) => ({
        transition, position, family,
        info: position === 'top' ? 'bash' : position === 'middle' ? 'python' : 'typescript',
        elementEndpoint: false,
        burstTyping: false
      }))));
  for (const burstTyping of [false, true]) {
    scenarios.push({ transition: 'literal prefix', position: 'tail', family: '~~~', info: 'bash', elementEndpoint: true, burstTyping });
  }
  scenarios.push({ transition: 'literal prefix', position: 'tail', family: '~~~', info: 'bash', elementEndpoint: false, burstTyping: true });

  // Formal own-node extents exclude separator rows. This deliberately does
  // not use the older synthetic fixture whose end lines tile the source gaps.
  const formalDocument = (markdown: string): FullOwnerAcceptedDocument => {
    const rows: FullOwnerRow[] = [];
    const html: string[] = [];
    for (const block of createEditorMarkdownBlockIndex(markdown, { referenceLabelCaseFoldProfile: 14 }).blocks) {
      const raw = markdown.slice(block.from, block.to).replace(/\n+$/u, '');
      if (!raw.trim()) continue;
      const id = `b${rows.length}`;
      const startLine = markdown.slice(0, block.from).split('\n').length - 1;
      rows.push({ id, startLine, endLine: startLine + raw.split('\n').length });
      if (block.kind === 'code') {
        const lines = raw.split('\n');
        const opening = /^(`{3,}|~{3,})(.*)$/u.exec(lines[0] ?? '');
        if (!opening || lines.at(-1) !== opening[1]) throw new Error('gap-formal-code-invalid');
        html.push(fullOwnerCodeBlock(`${lines.slice(1, -1).join('\n')}\n`, id, opening[2]!.trim()));
      } else if (block.kind === 'paragraph') {
        html.push(fullOwnerParagraphBlock(raw.replace(/\\([~`\\])/gu, '$1'), id));
      } else throw new Error('gap-formal-block-unsupported');
    }
    return { markdown, html: html.join(''), editMap: fullOwnerEditMap('gap-formal-response', rows) };
  };

  it.each(['~~~python', '```python'])('creates %s in a leading owned empty paragraph without changing following source', async (opening) => {
    vi.useFakeTimers();
    const initial = 'Before \\\\ path.\n\n\nMiddle.\n\nAfter.';
    const fixture = createFullOwnerFixture({ ...formalDocument(initial), signature: 'leading-owned-gap', sourceCaret: 0 });
    try {
      const original = fixture.surface.querySelector('p');
      const text = original?.firstChild;
      if (!(original instanceof HTMLParagraphElement) || !(text instanceof Text)) throw new Error('leading-gap-setup-invalid');
      fixture.surface.focus();
      placeCaretInText(text, 0);
      act(() => {
        const enter = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, key: 'Enter' });
        fixture.surface.dispatchEvent(enter);
        expect(enter.defaultPrevented).toBe(false);
        const native = window.getSelection()!;
        const range = native.getRangeAt(0).cloneRange();
        expect(fullOwnerDispatchBeforeInput(fixture.surface, { data: null, inputType: 'insertParagraph' }, range).defaultPrevented).toBe(false);
        const leading = original.cloneNode(false) as HTMLParagraphElement;
        leading.append(document.createElement('br'));
        original.before(leading);
        native.collapse(text, 0);
        fixture.surface.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertParagraph' }));
      });
      expect(fixture.history.getValue()).toBe('  \n\n' + initial);
      const native = window.getSelection()!;
      const leading = fixture.surface.firstElementChild;
      if (!(leading instanceof HTMLParagraphElement)) throw new Error('leading-gap-paragraph-missing');
      native.collapse(leading, 0);
      expect(serializeVisualMarkdown(fixture.surface)).toBe('Before \\\\ path.\n\nMiddle.\n\nAfter.');
      act(() => {
        for (const character of opening) {
          const range = native.getRangeAt(0).cloneRange();
          expect(fullOwnerDispatchBeforeInput(fixture.surface, { data: character, inputType: 'insertText' }, range).defaultPrevented,
            `character ${character}; failures ${JSON.stringify(fixture.onFailure.mock.calls)}`).toBe(false);
          if (range.startContainer instanceof Text) {
            range.startContainer.insertData(range.startOffset, character);
            native.collapse(range.startContainer, range.startOffset + 1);
          } else {
            const inserted = document.createTextNode(character);
            leading.replaceChildren(inserted);
            native.collapse(inserted, 1);
          }
          fixture.surface.dispatchEvent(new InputEvent('input', { bubbles: true, data: character, inputType: 'insertText' }));
        }
        fixture.surface.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, cancelable: true, key: 'Enter' }));
      });
      await act(async () => { vi.advanceTimersByTime(90); await Promise.resolve(); });
      expect(fixture.onFailure).not.toHaveBeenCalled();
      expect(fixture.onTransferFailure).not.toHaveBeenCalled();
      const fence = opening.slice(0, 3);
      expect(fixture.history.getValue()).toBe(`${opening}\n\n${fence}\n\n` + initial);
      const code = fixture.surface.querySelector('pre code');
      expect(code?.classList.contains('language-python')).toBe(true);
      if (!(code instanceof HTMLElement)) throw new Error('leading-gap-code-missing');
      act(() => {
        const range = native.getRangeAt(0).cloneRange();
        expect(fullOwnerDispatchBeforeInput(fixture.surface, { data: 'x', inputType: 'insertText' }, range).defaultPrevented).toBe(false);
        const inserted = document.createTextNode('x');
        code.replaceChildren(inserted);
        native.collapse(inserted, 1);
        fixture.surface.dispatchEvent(new InputEvent('input', { bubbles: true, data: 'x', inputType: 'insertText' }));
      });
      await act(async () => { vi.advanceTimersByTime(90); await Promise.resolve(); });
      expect(fixture.history.getValue()).toBe(`${opening}\nx\n${fence}\n\n` + initial);
      expect(fixture.onFailure).not.toHaveBeenCalled();
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it('reproduces the escaped literal fence Backspace on the formal slot paragraph', async () => {
    vi.useFakeTimers();
    const initial = 'Head\n\nSlot\n\nTail';
    const fixture = createFullOwnerFixture({
      ...formalDocument(initial),
      signature: 'formal-slot-fence',
      sourceCaret: 0
    });
    try {
      const blocks = createEditorMarkdownBlockIndex(initial, {
        referenceLabelCaseFoldProfile: 14
      }).blocks;
      const slot = blocks.find((block) =>
        block.kind === 'paragraph'
        && initial.slice(block.from, block.to).trim() === 'Slot');
      if (!slot) throw new Error('formal-slot-fence-block-missing');
      const paragraph = fixture.surface.querySelectorAll('p')[1];
      const text = paragraph?.firstChild;
      if (!(paragraph instanceof HTMLParagraphElement) || !(text instanceof Text)) {
        throw new Error('formal-slot-fence-paragraph-missing');
      }
      expect(text.data).toBe('Slot');
      const encoded = '\\`\\`\\`';
      fixture.surface.focus();
      const selection = window.getSelection();
      const selectAll = document.createRange();
      selectAll.setStart(text, 0);
      selectAll.setEnd(text, text.length);
      selection?.removeAllRanges();
      selection?.addRange(selectAll);
      const first = fullOwnerDispatchBeforeInput(
        fixture.surface,
        { data: '`', inputType: 'insertText' },
        fullOwnerTargetRange(text, 0, text.length)
      );
      if (first.defaultPrevented) throw new Error('formal-slot-fence-first-tick-prevented');
      text.replaceData(0, text.length, '`');
      selection?.collapse(text, 1);
      fixture.surface.dispatchEvent(
        new InputEvent('input', { bubbles: true, data: '`', inputType: 'insertText' })
      );
      for (let index = 0; index < 2; index += 1) {
        const inserted = fullOwnerNativeInsertAtSelection(fixture.surface, '`');
        if (inserted.prevented) throw new Error('formal-slot-fence-tick-prevented');
      }
      vi.advanceTimersByTime(90);
      expect(fixture.onFailure).not.toHaveBeenCalled();
      const sourceAfterTicks = fixture.history.getValue();
      expect(sourceAfterTicks).toBe(
        initial.slice(0, slot.from) + encoded + initial.slice(slot.to)
      );
      expect(text.data).toBe('```');
      const caretAfterTicks = slot.from + encoded.length;
      const deletion = fullOwnerNativeDelete(
        fixture.surface,
        text,
        text.length - 1,
        text.length,
        'deleteContentBackward'
      );
      if (deletion.prevented) throw new Error('formal-slot-fence-backspace-prevented');
      vi.advanceTimersByTime(90);
      expect(fixture.onFailure).not.toHaveBeenCalled();
      expect(fixture.history.getValue()).toBe(
        initial.slice(0, slot.from) + encoded.slice(0, -2) + initial.slice(slot.to)
      );
      expect(window.getSelection()?.anchorNode).not.toBe(fixture.surface);
      expect(text.data).toBe('``');
      void caretAfterTicks;
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it.for(scenarios)('$transition at $position with $family (element endpoint $elementEndpoint, burst $burstTyping) keeps every live caret through deletion and continuation', async (scenario, { task }) => {
    vi.useFakeTimers();
    const anchorText = 'Writing anchor';
    const leftFence = '```js\nLEFT_SENTINEL\n```';
    const rightFence = '```js\nRIGHT_SENTINEL\n```';
    const segments = scenario.position === 'top'
      ? [anchorText, rightFence, 'Following paragraph']
      : scenario.position === 'middle'
        ? [leftFence, anchorText, rightFence, 'Following paragraph']
        : [leftFence, 'Preceding paragraph', anchorText];
    const initial = segments.join('\n\n');
    const anchorEnd = initial.indexOf(anchorText) + anchorText.length;
    const point = anchorEnd + 2;
    const prefix = initial.slice(0, anchorEnd) + '\n\n';
    const suffix = initial.slice(anchorEnd);
    const emptyOwned = prefix + '  ' + suffix;
    const removedFrameSource = scenario.position === 'tail' ? initial : emptyOwned;
    const removedFrameCaret = scenario.position === 'tail' ? initial.length : point;
    const clearedLiteral = prefix + suffix;
    const input = scenario.family + scenario.info;
    const escapedFamily = Array.from(scenario.family, (marker) => `\\${marker}`).join('');
    const literalSource = prefix + escapedFamily + scenario.info + suffix;
    const codeSource = (text: string) => prefix + `${scenario.family}${scenario.info}\n${text}\n${scenario.family}` + suffix;
    const bodyStart = point + 3 + scenario.info.length + 1;
    const fixture = createFullOwnerFixture({
      ...formalDocument(initial), signature: `owned-gap-${scenario.position}-${scenario.family}`, sourceCaret: 0
    });
    const writes = vi.spyOn(fixture.history, 'applyTextChange');
    const undo = vi.spyOn(fixture.history, 'undo');
    const redo = vi.spyOn(fixture.history, 'redo');
    let disposed = false;
    fixture.onMarkdownChange.mockImplementation(() => {
      queueMicrotask(() => { if (!disposed) fixture.rerenderProps(); });
    });
    const receipt = {
      scenario, phase: 'setup', classification: 'SETUP_PENDING', admitted: false,
      steps: [] as unknown[], writes: [] as unknown[], commands: {} as unknown,
      error: null as string | null
    };
    Object.assign(task.meta, { ownedGapDeletion: receipt });
    type Kind = 'anchor' | 'paragraph' | 'code';
    const anchor = (): HTMLParagraphElement => {
      const result = Array.from(fixture.surface.querySelectorAll('p')).find((paragraph) =>
        paragraph.textContent === anchorText || paragraph.textContent === anchorText + 'q');
      if (!(result instanceof HTMLParagraphElement)) throw new Error('gap-anchor-paragraph-missing');
      return result;
    };
    const body = (kind: Kind): HTMLElement => {
      if (kind === 'anchor') return anchor();
      const next = anchor().nextElementSibling;
      const result = kind === 'code' ? next?.querySelector('code') : next;
      if (!(result instanceof HTMLElement)
        || (kind === 'paragraph' && !(result instanceof HTMLParagraphElement))) {
        throw new Error(`gap-${kind}-owner-missing`);
      }
      return result;
    };
    const semanticOffset = (root: HTMLElement, node: Node | null, offset: number): number | null => {
      if (!node || !root.contains(node)) return null;
      const range = document.createRange();
      range.selectNodeContents(root); range.setEnd(node, offset);
      return range.toString().length;
    };
    const nativeSummary = () => {
      const native = window.getSelection();
      let root: HTMLElement | null = native?.anchorNode instanceof HTMLElement
        ? native.anchorNode : native?.anchorNode?.parentElement ?? null;
      while (root && root.parentElement !== fixture.surface) root = root.parentElement;
      const content = root instanceof HTMLPreElement ? root.querySelector('code') : root;
      return { connected: Boolean(native?.anchorNode?.isConnected), rootTag: root?.tagName,
        rootText: root?.textContent, nodeName: native?.anchorNode?.nodeName,
        localOffset: native?.anchorOffset, collapsed: native?.isCollapsed,
        offset: content && native ? semanticOffset(content, native.anchorNode, native.anchorOffset) : null };
    };
    let sentinels = Array.from(fixture.surface.querySelectorAll('pre')).map((pre) => ({
      pre, text: pre.querySelector('code')?.textContent
    }));
    const checkNeighbors = (retainNodes = true): void => {
      const current = Array.from(fixture.surface.querySelectorAll('pre')).filter((pre) =>
        /(?:LEFT|RIGHT)_SENTINEL/u.test(pre.textContent ?? ''));
      expect(current.map((pre) => pre.querySelector('code')?.textContent)).toEqual(sentinels.map((item) => item.text));
      if (retainNodes) expect(current).toEqual(sentinels.map((item) => item.pre));
      else sentinels = current.map((pre) => ({ pre, text: pre.querySelector('code')?.textContent }));
    };
    const capture = (phase: string, expected?: string): void => {
      receipt.phase = phase;
      receipt.steps.push({ phase, expected, value: fixture.history.getValue(),
        selection: fixture.history.getSelection(), history: fixture.history.getHistoryState(),
        revision: fixture.history.getRevision?.(), native: nativeSummary(),
        pending: fixture.runtime().isTransferPending(), requests: fixture.requestPreview.mock.calls.length,
        failures: fixture.onFailure.mock.calls.map(([code]) => code),
        transferFailures: fixture.onTransferFailure.mock.calls.length });
    };
    const assertPoint = (kind: Kind, offset: number): void => {
      const root = body(kind), native = window.getSelection();
      expect(native?.isCollapsed, `${receipt.phase}: collapsed native selection`).toBe(true);
      expect(semanticOffset(root, native?.anchorNode ?? null, native?.anchorOffset ?? 0),
        `${receipt.phase}: live native anchor, never test-replayed`).toBe(offset);
      expect(semanticOffset(root, native?.focusNode ?? null, native?.focusOffset ?? 0)).toBe(offset);
      expect(document.activeElement).toBe(fixture.surface);
    };
    const advance = async (ms = 90): Promise<void> => {
      await act(async () => { vi.advanceTimersByTime(ms); await Promise.resolve(); });
    };
    const acceptRequested = async (expected: string): Promise<boolean> => {
      if (!fixture.runtime().isTransferPending()) return false;
      expect(fixture.requestPreview.mock.calls.at(-1)?.[0]).toBe(expected);
      act(() => fixture.accept(formalDocument(expected)));
      await advance(0); checkNeighbors(false);
      return true;
    };
    const state = async (phase: string, expected: string, caret: number, kind: Kind, offset: number): Promise<void> => {
      await advance(); capture(phase, expected);
      expect(fixture.history.getValue(), `${phase}: exact canonical source`).toBe(expected);
      await acceptRequested(expected);
      expect(fixture.history.getSelection(), `${phase}: canonical caret`).toEqual({ direction: 'none', start: caret, end: caret });
      assertPoint(kind, offset); checkNeighbors();
      expect(fixture.history.getHistoryState().redoDepth).toBe(0);
      expect(fixture.runtime().isEditable()).toBe(true);
      expect(fixture.onFailure.mock.calls, phase).toEqual([]);
      expect(fixture.onTransferFailure.mock.calls, phase).toEqual([]);
    };
    const key = (name: string): KeyboardEvent => {
      const event = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, key: name });
      fixture.surface.dispatchEvent(event); return event;
    };
    // Native defaults read the live Selection. Neither driver places a caret
    // before an event: doing so would hide the reported jump to article start.
    const insert = (character: string, kind: Kind, offset: number): void => {
      assertPoint(kind, offset);
      if (key(character).defaultPrevented) return;
      const native = window.getSelection();
      const range = native?.rangeCount ? native.getRangeAt(0).cloneRange() : null;
      if (!range || !native) throw new Error('gap-native-insert-range-missing');
      const before = fullOwnerDispatchBeforeInput(fixture.surface, { data: character, inputType: 'insertText' }, range.cloneRange());
      if (before.defaultPrevented) return;
      if (range.startContainer instanceof Text) {
        const node = range.startContainer, at = range.startOffset;
        node.insertData(at, character); native.collapse(node, at + character.length);
      } else {
        const root = body(kind), node = document.createTextNode(character);
        if (root instanceof HTMLParagraphElement && !root.textContent && root.firstChild instanceof HTMLBRElement) root.replaceChildren(node);
        else range.insertNode(node);
        native.collapse(node, character.length);
      }
      fixture.surface.dispatchEvent(new InputEvent('input', { bubbles: true, data: character, inputType: 'insertText' }));
    };
    const textBoundary = (root: HTMLElement, offset: number): { node: Text; offset: number } => {
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      let remaining = offset;
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!(node instanceof Text)) continue;
        if (remaining <= node.length) return { node, offset: remaining };
        remaining -= node.length;
      }
      throw new Error('gap-native-delete-text-boundary-missing');
    };
    const backspace = (kind: Kind, offset: number, join = false): void => {
      assertPoint(kind, offset);
      if (key('Backspace').defaultPrevented) return;
      const root = body(kind), native = window.getSelection();
      if (!native) throw new Error('gap-native-delete-selection-missing');
      const target = document.createRange();
      if (offset > 0) {
        const start = textBoundary(root, offset - 1), end = textBoundary(root, offset);
        target.setStart(start.node, start.offset); target.setEnd(end.node, end.offset);
      } else if (join && root instanceof HTMLParagraphElement && !root.textContent) {
        const preceding = anchor().firstChild;
        if (!(preceding instanceof Text) || root.previousElementSibling !== anchor()) throw new Error('gap-native-join-predecessor-invalid');
        target.setStart(preceding, preceding.length); target.setEnd(root, 0);
      } else throw new Error('gap-native-backspace-was-not-owned');
      const before = fullOwnerDispatchBeforeInput(fixture.surface, { data: null, inputType: 'deleteContentBackward' }, target.cloneRange());
      if (before.defaultPrevented) return;
      if (join) {
        const preceding = anchor().firstChild;
        if (!(preceding instanceof Text)) throw new Error('gap-native-join-text-missing');
        root.remove(); native.collapse(preceding, preceding.length);
      } else {
        target.deleteContents(); native.removeAllRanges(); native.addRange(target);
        if (root instanceof HTMLParagraphElement && !root.textContent) {
          root.replaceChildren(document.createElement('br')); native.collapse(root, 0);
        }
      }
      fixture.surface.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'deleteContentBackward' }));
    };
    const historyStep = async (isRedo: boolean, expected: string, caret: number, kind: Kind, offset: number, phase: string): Promise<void> => {
      const before = fixture.history.getHistoryState();
      act(() => fullOwnerHistoryKey(fixture.surface, isRedo));
      await advance(0); capture(phase, expected);
      expect(fixture.history.getValue(), `${phase}: original CodeMirror result`).toBe(expected);
      await acceptRequested(expected);
      expect(fixture.history.getSelection()).toEqual({ direction: 'none', start: caret, end: caret });
      expect(fixture.history.getHistoryState()).toEqual({
        undoDepth: before.undoDepth + (isRedo ? 1 : -1), redoDepth: before.redoDepth + (isRedo ? -1 : 1)
      });
      assertPoint(kind, offset); checkNeighbors(false);
      expect(fixture.onFailure.mock.calls, phase).toEqual([]);
      expect(fixture.onTransferFailure.mock.calls, phase).toEqual([]);
    };
    try {
      capture('setup formal admission', initial);
      expect(fixture.history.getValue()).toBe(initial);
      expect(fixture.runtime().isEditable()).toBe(true);
      expect(fixture.history.getSelection()).toEqual({ direction: 'none', start: 0, end: 0 });
      const firstText = anchor().firstChild;
      if (!(firstText instanceof Text)) throw new Error('gap-initial-anchor-text-missing');
      fixture.surface.focus(); placeCaretInText(firstText, firstText.length);
      if (scenario.elementEndpoint) {
        const range = document.createRange();
        range.selectNodeContents(anchor()); range.collapse(false);
        window.getSelection()?.removeAllRanges(); window.getSelection()?.addRange(range);
      }
      act(() => {
        const enter = key('Enter');
        if (enter.defaultPrevented) return;
        const native = window.getSelection();
        const range = native?.rangeCount ? native.getRangeAt(0).cloneRange() : null;
        if (!range || !native || range.startContainer !== (scenario.elementEndpoint ? anchor() : firstText)
          || range.startOffset !== (scenario.elementEndpoint ? anchor().childNodes.length : firstText.length)) {
          throw new Error('gap-native-Enter-endpoint-invalid');
        }
        const before = fullOwnerDispatchBeforeInput(fixture.surface, { data: null, inputType: 'insertParagraph' }, range);
        if (before.defaultPrevented) return;
        // Chromium's genuine Enter default clones this P's block ID. The
        // duplicate is part of the operation, not an invented idless row.
        const original = anchor();
        const next = original.cloneNode(false) as HTMLParagraphElement;
        next.append(document.createElement('br')); original.after(next); native.collapse(next, 0);
        expect(next.getAttribute('data-easymde-visual-block-id')).toBe(original.getAttribute('data-easymde-visual-block-id'));
        fixture.surface.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertParagraph' }));
      });
      await state('setup genuine cloned-P Enter', emptyOwned, point, 'paragraph', 0);
      expect(body('paragraph').firstChild).toBeInstanceOf(HTMLBRElement);
      expect(body('paragraph').getAttribute('data-easymde-visual-block-id')).toBe(anchor().getAttribute('data-easymde-visual-block-id'));
      receipt.admitted = true; receipt.classification = 'VALID_CONSUMER_RUNNING';

      for (let count = 1; count <= input.length; count += 1) {
        act(() => insert(input[count - 1]!, 'paragraph', count - 1));
        if (scenario.elementEndpoint && count === input.length) {
          act(() => {
            backspace('paragraph', count);
            assertPoint('paragraph', count - 1);
            expect(body('paragraph').textContent).toBe(input.slice(0, -1));
            insert(input[count - 1]!, 'paragraph', count - 1);
          });
        }
        const encoded = count < 3 ? input.slice(0, count) : escapedFamily + input.slice(3, count);
        if (scenario.burstTyping && count < input.length) {
          assertPoint('paragraph', count);
          expect(body('paragraph').textContent).toBe(input.slice(0, count));
          continue;
        }
        await state(`literal key ${count}`, prefix + encoded + suffix, point + encoded.length, 'paragraph', count);
        expect(body('paragraph').textContent).toBe(input.slice(0, count));
      }
      expect(fixture.history.getValue()).toBe(literalSource);
      const protectedCount = sentinels.length;
      expect(fixture.surface.querySelectorAll('pre')).toHaveLength(protectedCount);

      if (scenario.transition === 'literal prefix') {
        const units = [...Array.from(scenario.family, (marker) => `\\${marker}`), ...scenario.info];
        const canonicalStates = Array.from({ length: input.length + 1 }, (_, completed) => {
          const encoded = units.slice(0, input.length - completed).join('');
          return { value: prefix + encoded + suffix, caret: point + encoded.length };
        });
        const beforeBurstHistory = fixture.history.getHistoryState();
        const beforeBurstRevision = fixture.history.getRevision?.();
        expect(beforeBurstRevision).toBeTypeOf('number');
        let previousProgress = 0;
        let previousRevision = beforeBurstRevision as number;
        let previousHistory = beforeBurstHistory;
        const burstClock = Date.now();
        act(() => {
          for (let completed = 1; completed <= input.length; completed += 1) {
            const remaining = input.length - completed;
            receipt.phase = `literal rapid Backspace ${completed}`;
            backspace('paragraph', remaining + 1);
            capture(receipt.phase, canonicalStates[completed]!.value);
            expect(Date.now(), 'no debounce advance between native deletion keys').toBe(burstClock);
            assertPoint('paragraph', remaining);
            expect(body('paragraph').textContent).toBe(input.slice(0, remaining));
            expect(fixture.surface.querySelectorAll('pre')).toHaveLength(protectedCount);
            checkNeighbors();
            expect(fixture.onFailure.mock.calls, receipt.phase).toEqual([]);
            expect(fixture.onTransferFailure.mock.calls, receipt.phase).toEqual([]);

            // Canonical may lag a native burst, but only at an exact already
            // authored prefix state. Never infer an expected value by copying
            // the current document or normalize away its surrounding bytes.
            const value = fixture.history.getValue();
            const progress = canonicalStates.findIndex((candidate) => candidate.value === value);
            const revision = fixture.history.getRevision?.();
            const history = fixture.history.getHistoryState();
            receipt.steps.push({ phase: receipt.phase, nativeCompleted: completed,
              canonicalCompleted: progress, previousCanonicalCompleted: previousProgress,
              value, selection: fixture.history.getSelection(), revision, history });
            expect(progress, 'canonical is one exact completed native-edit state').toBeGreaterThanOrEqual(0);
            expect(progress, 'canonical commit progress never moves backward').toBeGreaterThanOrEqual(previousProgress);
            expect(progress, 'canonical cannot commit a native key not yet authored').toBeLessThanOrEqual(completed);
            expect(fixture.history.getSelection()).toEqual({
              direction: 'none', start: canonicalStates[progress]!.caret, end: canonicalStates[progress]!.caret
            });
            expect(revision).toBeTypeOf('number');
            if (progress === previousProgress) {
              expect(revision, 'a still-pending native key is not a canonical write').toBe(previousRevision);
              expect(history).toEqual(previousHistory);
            } else {
              const revisionDelta = (revision as number) - previousRevision;
              expect(revisionDelta).toBeGreaterThanOrEqual(1);
              expect(revisionDelta).toBeLessThanOrEqual(progress - previousProgress);
              expect(history.undoDepth - previousHistory.undoDepth).toBeGreaterThanOrEqual(0);
              expect(history.undoDepth - previousHistory.undoDepth).toBeLessThanOrEqual(revisionDelta);
              expect(history.redoDepth).toBe(0);
            }
            previousProgress = progress;
            previousRevision = revision as number;
            previousHistory = history;
          }
        });
        // Exactly one commit boundary follows the whole info/marker deletion
        // burst. No per-key timer flush, Preview acceptance or caret rescue.
        await state('literal rapid burst committed', clearedLiteral, point, 'paragraph', 0);
        const burstHistory = fixture.history.getHistoryState();
        const burstRevision = fixture.history.getRevision?.();
        expect(burstRevision).toBeTypeOf('number');
        expect((burstRevision as number) - (beforeBurstRevision as number)).toBeGreaterThanOrEqual(1);
        expect((burstRevision as number) - (beforeBurstRevision as number)).toBeLessThanOrEqual(input.length);
        expect(burstHistory.undoDepth - beforeBurstHistory.undoDepth).toBeGreaterThanOrEqual(1);
        expect(burstHistory.undoDepth - beforeBurstHistory.undoDepth).toBeLessThanOrEqual(input.length);
        expect(burstHistory.redoDepth).toBe(0);
        act(() => insert('q', 'paragraph', 0));
        await state('literal continuation q', prefix + 'q' + suffix, point + 1, 'paragraph', 1);
        act(() => backspace('paragraph', 1));
        await state('literal continuation delete', clearedLiteral, point, 'paragraph', 0);
        await historyStep(false, prefix + 'q' + suffix, point + 1, 'paragraph', 1, 'literal Undo final deletion');
        await historyStep(true, clearedLiteral, point, 'paragraph', 0, 'literal Redo final deletion');
      } else {
        act(() => { assertPoint('paragraph', input.length); expect(key('Enter').defaultPrevented).toBe(true); });
        await state('created fence Enter', codeSource(''), bodyStart, 'code', 0);
        expect(fixture.surface.querySelectorAll('pre')).toHaveLength(protectedCount + 1);
        expect(body('code').classList.contains(`language-${scenario.info}`)).toBe(true);
        act(() => insert('a', 'code', 0));
        await state('created body a', codeSource('a'), bodyStart + 1, 'code', 1);
        act(() => insert('b', 'code', 1));
        await state('created body ab', codeSource('ab'), bodyStart + 2, 'code', 2);
        const pendingBefore = fixture.history.getHistoryState();
        act(() => backspace('code', 2));
        capture('rapid body first deletion pending', codeSource('ab'));
        assertPoint('code', 1);
        expect(fixture.history.getValue()).toBe(codeSource('ab'));
        expect(fixture.history.getHistoryState()).toEqual(pendingBefore);
        act(() => backspace('code', 1));
        capture('rapid body final deletion pending', codeSource('ab'));
        assertPoint('code', 0);
        expect(fixture.history.getValue()).toBe(codeSource('ab'));
        expect(fixture.history.getHistoryState()).toEqual(pendingBefore);
        // No timer flush or test caret replacement between the final native
        // deletion and the empty-CODE structural Backspace.
        act(() => backspace('code', 0));
        await state('created empty frame exit', removedFrameSource, removedFrameCaret, 'paragraph', 0);
        expect(fixture.history.getHistoryState().undoDepth).toBe(pendingBefore.undoDepth + 2);
        expect(fixture.surface.querySelectorAll('pre')).toHaveLength(protectedCount);
        await historyStep(false, codeSource(''), bodyStart, 'code', 0, 'Undo frame exit');
        await historyStep(false, codeSource('ab'), bodyStart + 2, 'code', 2, 'Undo final body deletion');
        await historyStep(true, codeSource(''), bodyStart, 'code', 0, 'Redo final body deletion');
        await historyStep(true, removedFrameSource, removedFrameCaret, 'paragraph', 0, 'Redo frame exit');
        act(() => backspace('paragraph', 0, true));
        await state('extra native join Backspace', initial, anchorEnd, 'anchor', anchorText.length);
        act(() => insert('q', 'anchor', anchorText.length));
        const continued = initial.slice(0, anchorEnd) + 'q' + initial.slice(anchorEnd);
        await state('post-frame continuation q', continued, anchorEnd + 1, 'anchor', anchorText.length + 1);
        act(() => backspace('anchor', anchorText.length + 1));
        await state('post-frame continuation deletion', initial, anchorEnd, 'anchor', anchorText.length);
        await historyStep(false, continued, anchorEnd + 1, 'anchor', anchorText.length + 1, 'Undo continuation deletion');
        await historyStep(true, initial, anchorEnd, 'anchor', anchorText.length, 'Redo continuation deletion');
      }
      capture('complete'); receipt.classification = 'GREEN';
    } catch (error) {
      receipt.error = error instanceof Error ? error.message : String(error);
      receipt.classification = receipt.admitted ? 'CONSUMER_RED' : 'SETUP_FAILURE';
      capture(receipt.phase);
      throw error;
    } finally {
      receipt.writes = writes.mock.calls.map(([change], index) => ({ change,
        result: { type: writes.mock.results[index]?.type, value: writes.mock.results[index]?.value ?? null } }));
      receipt.commands = { undo: undo.mock.results.map((result) => ({ type: result.type, value: result.value })),
        redo: redo.mock.results.map((result) => ({ type: result.type, value: result.value })) };
      disposed = true; writes.mockRestore(); undo.mockRestore(); redo.mockRestore();
      fixture.unmount(); vi.useRealTimers();
    }
  });
});


// The measured chain in one document: an emptied terminal heading is
// respelled as a paragraph (the shortcut), then the browser names the next
// press by the preceding row's text tail while a reference definition the
// renderer hides still sits between them, and then ordinary typing must still
// land. Each step owns its own canonical bytes, so the source and the surface
// stay one pairing throughout.
it('keeps the emptied terminal chain consistent across its shortcut, its join and the next key', async () => {
  vi.useFakeTimers();
  const accepted = fullDuplicateSeparatorDocument();
  const signature = 'terminal-chain';
  const fixture = createFullOwnerFixture({
    editMap: null,
    html: accepted.html,
    markdown: accepted.markdown,
    signature,
    sourceCaret: accepted.markdown.length - 1
  });
  const settle = async (): Promise<void> => {
    await act(async () => { vi.advanceTimersByTime(160); await Promise.resolve(); });
  };
  try {
    const heading = fixture.surface.querySelectorAll('h2')[1];
    if (!(heading instanceof HTMLElement)) throw new Error('terminal-chain-heading-missing');
    fixture.surface.focus();
    window.getSelection()?.collapse(heading, 0);

    // The emptied heading's own row goes; the earlier `## 22. Ref` row stays.
    expect(pressFullBackspaceKey(fixture.surface)).toBe(true);
    await settle();
    expect(fixture.onFailure).not.toHaveBeenCalled();
    expect(fixture.history.getValue()).toBe(
      'Para\n\n## 22. Ref\n\nBody.\n\n[ref]: https://example.com "Example"\n\n\n\n'
    );

    // The emptied paragraph joins the preceding row, across the hidden
    // definition: the owner reads the trailing separator run, not the press's
    // text point, so the definition is never treated as block text.
    const emptied = fixture.surface.querySelector('[data-easymde-visual-block-id="b3"]');
    const text = fixture.surface.querySelector('[data-easymde-visual-block-id="b2"]')?.firstChild;
    if (!(emptied instanceof HTMLElement) || !(text instanceof Text)) {
      throw new Error('terminal-chain-join-fixture-invalid');
    }
    const caret = document.createRange();
    caret.setStart(emptied, 0);
    caret.collapse(true);
    window.getSelection()?.removeAllRanges();
    window.getSelection()?.addRange(caret);
    const target = document.createRange();
    target.setStart(text, text.length);
    target.setEnd(emptied, 0);
    const join = fullOwnerDispatchBeforeInput(
      fixture.surface,
      { data: null, inputType: 'deleteContentBackward' },
      target.cloneRange()
    );
    expect(join.defaultPrevented).toBe(true);
    await settle();
    expect(fixture.onFailure).not.toHaveBeenCalled();
    expect(fixture.history.getValue()).toBe(
      'Para\n\n## 22. Ref\n\nBody.\n\n[ref]: https://example.com "Example"'
    );
    expect(fixture.history.getSelection()).toEqual({ direction: 'none', end: 61, start: 61 });
    expect(emptied.isConnected).toBe(false);

    // The caret is not stranded: the next key is ordinary native input again.
    const tail = fixture.surface.querySelector('[data-easymde-visual-block-id="b2"]')?.firstChild;
    if (!(tail instanceof Text)) throw new Error('terminal-chain-tail-missing');
    expect(fullOwnerNativeInsert(fixture.surface, tail, tail.length, 'Z').prevented).toBe(false);
    await settle();
    expect(fixture.onFailure).not.toHaveBeenCalled();
    expect(fixture.onTransferFailure).not.toHaveBeenCalled();
    expect(fixture.history.getValue()).toBe(
      'Para\n\n## 22. Ref\n\nBody.Z\n\n[ref]: https://example.com "Example"'
    );
    expect(fixture.runtime().isEditable()).toBe(true);
  } finally {
    fixture.unmount();
    vi.useRealTimers();
  }
});

// A rendered paragraph whose own row is followed by source that renders to
// nothing. The definition spells the destination and title the serializer
// writes inline for the link that *does* render, so a character diff over the
// source and the baseline finds those bytes on both sides and matches the
// definition to the rendered link; the row's own tail is then left with no
// source offset at all and every caret inside it fails closed. The press here
// is an ordinary in-text backward deletion at that tail, so it must delete
// exactly the character it names and leave the definition intact.
it('maps a paragraph-tail Backspace when a hidden reference definition follows its row', async () => {
  vi.useFakeTimers();
  const signature = 'hidden-reference-tail';
  const markdown = [
    'Lead',
    '',
    '这是一个 [OpenAI][openai-link] 链接。',
    '',
    '[openai-link]: https://openai.com "OpenAI"'
  ].join('\n');
  const html = fullOwnerParagraphBlock('Lead', 'b0')
    + fullOwnerBlock(
      '<p>这是一个 <a href="https://openai.com" title="OpenAI">OpenAI</a> 链接。</p>',
      'b1'
    );
  const editMap = fullOwnerEditMap(signature, [
    { endLine: 1, id: 'b0', startLine: 0 },
    { endLine: 3, id: 'b1', startLine: 2 }
  ]);
  const fixture = createFullOwnerFixture({
    editMap,
    html,
    markdown,
    signature,
    sourceCaret: markdown.length
  });
  const settle = async (): Promise<void> => {
    await act(async () => {
      vi.advanceTimersByTime(160);
      await Promise.resolve();
    });
  };
  try {
    fixture.surface.focus();
    const text = fixture.surface.querySelector(
      '[data-easymde-visual-block-id="b1"]'
    )?.lastChild;
    if (!(text instanceof Text)) {
      throw new Error('hidden-reference-tail-text-missing');
    }
    expect(text.data).toBe(' 链接。');
    placeCaretInText(text, text.length);
    const event = fullOwnerDispatchBeforeInput(
      fixture.surface,
      { data: null, inputType: 'deleteContentBackward' },
      fullOwnerTargetRange(text, text.length - 1, text.length)
    );
    expect(event.defaultPrevented).toBe(false);
    text.deleteData(text.length - 1, 1);
    placeCaretInText(text, text.length);
    fixture.surface.dispatchEvent(
      new InputEvent('input', {
        bubbles: true,
        inputType: 'deleteContentBackward'
      })
    );
    await settle();
    expect(fixture.onFailure).not.toHaveBeenCalled();
    expect(fixture.history.getValue()).toBe(
      'Lead\n\n这是一个 [OpenAI][openai-link] 链接\n\n'
        + '[openai-link]: https://openai.com "OpenAI"'
    );
    expect(fixture.runtime().isEditable()).toBe(true);
  } finally {
    fixture.unmount();
    vi.useRealTimers();
  }
});

// The same suffix is also the position a caret at the visual end of the
// document names, so an insertion there must still land at the end of the
// drawn row — in front of the definitions, never inside them.
it('inserts at the visual end of a row a hidden reference definition follows', async () => {
  vi.useFakeTimers();
  const signature = 'hidden-reference-tail-insert';
  const markdown = 'Lead\n\nPara\n\n[ref]: https://example.com "Example"';
  const html = fullOwnerParagraphBlock('Lead', 'b0')
    + fullOwnerParagraphBlock('Para', 'b1');
  const editMap = fullOwnerEditMap(signature, [
    { endLine: 1, id: 'b0', startLine: 0 },
    { endLine: 3, id: 'b1', startLine: 2 }
  ]);
  const fixture = createFullOwnerFixture({
    editMap, html, markdown, signature, sourceCaret: markdown.length
  });
  const settle = async (): Promise<void> => {
    await act(async () => { vi.advanceTimersByTime(160); await Promise.resolve(); });
  };
  try {
    fixture.surface.focus();
    const text = fullOwnerTextAt(fixture.surface, '[data-easymde-visual-block-id="b1"]');
    const result = fullOwnerNativeInsert(fixture.surface, text, text.length, 'X');
    await settle();
    expect({
      failures: vi.mocked(fixture.onFailure).mock.calls.map(([code]) => code),
      prevented: result.prevented,
      source: fixture.history.getValue()
    }).toEqual({ failures: [], prevented: false, source: 'Lead\n\nParaX\n\n[ref]: https://example.com "Example"' });
  } finally {
    fixture.unmount();
    vi.useRealTimers();
  }
});

/**
 * An ordinary Backspace/Delete is never allowed to break the session.
 *
 * The editor still refuses a press it cannot prove - nothing is written and the
 * canonical source never moves - but the refusal is silent: no failure code
 * reaches Root, no snapshot rollback claims a pairing this owner cannot prove,
 * no transfer failure locks the surface, and the user keeps typing and undo.
 * The only trace is the repair count published on the surface, which is a
 * diagnostic counter and never a failure code. Every non-deletion press keeps
 * its truthful failure.
 */
describe('ImmersiveVisualEditor deletion refusal policy', () => {
  /** Two rows: one the map can name, one whose DOM spelling the source lacks. */
  const createDeletionPolicyFixture = (
    signature: string
  ): Readonly<{ fixture: ReturnType<typeof createFullOwnerFixture>; markdown: string }> => {
    const markdown = 'Alpha text.\n\nOther text.\n';
    return {
      fixture: createFullOwnerFixture({
        editMap: fullOwnerEditMap(signature, [
          { endLine: 1, id: 'b0', startLine: 0 },
          { endLine: 3, id: 'b1', startLine: 2 }
        ]),
        html: fullOwnerParagraphBlock('Alpha text.', 'b0')
          + fullOwnerParagraphBlock('Rendered text.', 'b1'),
        markdown,
        signature,
        sourceCaret: 0
      }),
      markdown
    };
  };

  it('refuses an unmappable deletion without writing or reporting, and the next Backspace still works', () => {
    vi.useFakeTimers();
    const { fixture, markdown } = createDeletionPolicyFixture('deletion-policy-refusal');
    try {
      fixture.surface.focus();
      const unmappable = fullOwnerTextAt(
        fixture.surface,
        '[data-easymde-visual-block-id="b1"]'
      );
      placeCaretInText(unmappable, 4);
      let refused!: InputEvent;
      act(() => {
        refused = fullOwnerDispatchBeforeInput(
          fixture.surface,
          { data: null, inputType: 'deleteContentBackward' },
          fullOwnerTargetRange(unmappable, 3, 4)
        );
      });
      expect(refused.defaultPrevented).toBe(true);
      // Nothing written, nothing reported, nothing locked.
      expect(fixture.history.getValue()).toBe(markdown);
      expect(fixture.history.getHistoryState()).toEqual({ redoDepth: 0, undoDepth: 0 });
      expect(fixture.onFailure).not.toHaveBeenCalled();
      expect(fixture.onTransferFailure).not.toHaveBeenCalled();
      expect(fixture.runtime().isEditable()).toBe(true);
      // The caret and the surface are exactly where the user left them.
      expect(window.getSelection()?.anchorNode).toBe(unmappable);
      expect(window.getSelection()?.anchorOffset).toBe(4);
      expect(unmappable.data).toBe('Rendered text.');
      // The only trace is the diagnostic counter, never a failure code.
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair')
      ).toBe('1');

      // The next Backspace is a live key: a mappable deletion still commits.
      const mappable = fullOwnerTextAt(
        fixture.surface,
        '[data-easymde-visual-block-id="b0"]'
      );
      const deleted = fullOwnerNativeDelete(
        fixture.surface,
        mappable,
        mappable.length - 1,
        mappable.length,
        'deleteContentBackward'
      );
      expect(deleted.prevented).toBe(false);
      act(() => vi.advanceTimersByTime(160));
      expect(fixture.history.getValue()).toBe('Alpha text\n\nOther text.\n');
      expect(fixture.onFailure).not.toHaveBeenCalled();
      expect(fixture.onTransferFailure).not.toHaveBeenCalled();
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it('re-derives a diverged surface after a refused deletion and the next insertion commits', () => {
    vi.useFakeTimers();
    const signature = 'deletion-policy-repair';
    const markdown = 'Alpha\n\nBeta\n';
    const fixture = createFullOwnerFixture({
      editMap: fullOwnerEditMap(signature, [
        { endLine: 1, id: 'b0', startLine: 0 },
        { endLine: 3, id: 'b1', startLine: 2 }
      ]),
      html: fullOwnerParagraphBlock('Alpha', 'b0')
        + fullOwnerParagraphBlock('Beta', 'b1'),
      markdown,
      signature,
      sourceCaret: markdown.length
    });
    try {
      fixture.surface.focus();
      const alphaRow = fixture.surface.querySelector(
        '[data-easymde-visual-block-id="b0"]'
      );
      const betaRow = fixture.surface.querySelector(
        '[data-easymde-visual-block-id="b1"]'
      );
      const alphaText = alphaRow?.firstChild;
      const betaText = betaRow?.firstChild;
      if (
        !(alphaText instanceof Text)
        || !(betaText instanceof Text)
        || !(betaRow instanceof HTMLElement)
      ) throw new Error('deletion-policy-repair-fixture-invalid');
      // The unconsumed native structural merge: both rows become one paragraph
      // and the accepted two-row render no longer describes this window.
      alphaText.appendData(betaText.data);
      betaRow.remove();
      placeCaretInText(alphaText, alphaText.data.length);
      let refused!: InputEvent;
      act(() => {
        refused = fullOwnerDispatchBeforeInput(
          fixture.surface,
          { data: null, inputType: 'deleteContentBackward' },
          fullOwnerTargetRange(alphaText, alphaText.data.length - 1, alphaText.data.length)
        );
      });
      expect(refused.defaultPrevented).toBe(true);
      // The diverged surface was re-derived from the accepted render, silently:
      // no failure code, no transfer failure, no lock.
      expect(fixture.onFailure).not.toHaveBeenCalled();
      expect(fixture.onTransferFailure).not.toHaveBeenCalled();
      expect(fixture.runtime().isEditable()).toBe(true);
      expect(fixture.history.getValue()).toBe(markdown);
      expect(fixture.history.getHistoryState()).toEqual({ redoDepth: 0, undoDepth: 0 });
      expect(fixture.surface.children.length).toBe(2);
      const repairedBeta = fullOwnerTextAt(
        fixture.surface,
        '[data-easymde-visual-block-id="b1"]'
      );
      expect(repairedBeta).not.toBe(betaText);
      expect(repairedBeta.data).toBe('Beta');
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair')
      ).toBe('1');

      // The very next insertion commits against the restored surface.
      const inserted = fullOwnerNativeInsert(
        fixture.surface,
        repairedBeta,
        repairedBeta.length,
        '!'
      );
      act(() => vi.advanceTimersByTime(160));
      expect({
        failures: fixture.onFailure.mock.calls.map(([code]) => code),
        prevented: inserted.prevented,
        source: fixture.history.getValue(),
        transferFailures: fixture.onTransferFailure.mock.calls.length
      }).toEqual({
        failures: [],
        prevented: false,
        source: 'Alpha\n\nBeta!\n',
        transferFailures: 0
      });
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it('still reports the stable failure for a non-deletion input at the same unmappable caret', () => {
    vi.useFakeTimers();
    const { fixture, markdown } = createDeletionPolicyFixture('deletion-policy-non-deletion');
    try {
      fixture.surface.focus();
      const unmappable = fullOwnerTextAt(
        fixture.surface,
        '[data-easymde-visual-block-id="b1"]'
      );
      placeCaretInText(unmappable, 4);
      let inserted!: InputEvent;
      act(() => {
        inserted = fullOwnerDispatchBeforeInput(
          fixture.surface,
          { data: 'Z', inputType: 'insertText' },
          fullOwnerTargetRange(unmappable, 3, 3)
        );
      });
      expect(inserted.defaultPrevented).toBe(true);
      // An insertion is not a deletion: its failure is still truthful.
      expect(fixture.onFailure.mock.calls).toEqual([
        ['visual-editor-selection-map-failed']
      ]);
      expect(fixture.history.getValue()).toBe(markdown);
      expect(unmappable.data).toBe('Rendered text.');
      // The deletion-only diagnostic counter never moved.
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair')
      ).toBeNull();
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });
});

/**
 * The reported stall: a paragraph whose source line ends with a space, and
 * whose block is followed by another one.
 *
 * The serializer drops a block-terminal space, so the accepted baseline spells
 * that paragraph without it while the surface and the canonical source both
 * keep it. A caret at the run's own end therefore names a boundary the
 * alignment can only describe through the hidden range the trimmed space left
 * behind, and a press it could not describe was refused: nothing was written,
 * no failure was reported, and every later press at that caret was refused the
 * same way - the block simply stopped deleting.
 *
 * Both spellings of that space are covered here, because both occur in one real
 * burst: the browser respells the now-terminal space as an NBSP, and the
 * accepted render spells it back as the ASCII space the source carries.
 */
it('deletes a paragraph block-terminal space the serializer trims, and the block after it still deletes', async () => {
  vi.useFakeTimers();
  const signature = 'terminal-space-paragraph-deletion';
  const run = '支持 Emoji：😀 😎 🎉 🔥 💡 ✅';
  const markdown = `${run} \n\nNext para\n`;
  const fixture = createFullOwnerFixture({
    editMap: fullOwnerEditMap(signature, [
      { endLine: 1, id: 'b0', startLine: 0 },
      { endLine: 3, id: 'b1', startLine: 2 }
    ]),
    html: fullOwnerParagraphBlock(`${run} `, 'b0')
      + fullOwnerParagraphBlock('Next para', 'b1'),
    markdown,
    signature,
    sourceCaret: 0
  });
  const settle = async (): Promise<void> => {
    await act(async () => { vi.advanceTimersByTime(160); await Promise.resolve(); });
  };
  try {
    fixture.surface.focus();
    const text = fullOwnerTextAt(
      fixture.surface,
      '[data-easymde-visual-block-id="b0"]'
    );
    expect(text.data).toBe(`${run} `);
    // The browser's own spelling of a space that just became the run's last
    // character: the first Backspace deletes it, not the letter before it.
    text.replaceData(text.length - 1, 1, '\u00a0');
    const space = fullOwnerNativeDelete(
      fixture.surface,
      text,
      text.length - 1,
      text.length,
      'deleteContentBackward'
    );
    expect(space.prevented, 'the terminal space is an ordinary deletion').toBe(false);
    await settle();
    expect(fixture.history.getValue(), 'exactly the space is gone')
      .toBe(`${run}\n\nNext para\n`);
    expect(fixture.onFailure.mock.calls).toEqual([]);
    expect(fixture.onTransferFailure).not.toHaveBeenCalled();
    expect(
      fixture.surface.getAttribute('data-easymde-visual-deletion-repair'),
      'nothing was refused'
    ).toBeNull();
    expect(fixture.runtime().isEditable()).toBe(true);

    // The same block keeps deleting: the letter before the space is now the
    // run's own end, in the accepted render's ASCII spelling.
    const letter = fullOwnerNativeDelete(
      fixture.surface,
      text,
      text.length - 1,
      text.length,
      'deleteContentBackward'
    );
    expect(letter.prevented, 'the next press is an ordinary deletion').toBe(false);
    await settle();
    expect(fixture.history.getValue()).toBe(`${run.slice(0, -1)}\n\nNext para\n`);

    // And so does the block after it: one refused press may never leave the
    // rest of the document unable to delete.
    const next = fullOwnerTextAt(
      fixture.surface,
      '[data-easymde-visual-block-id="b1"]'
    );
    const following = fullOwnerNativeDelete(
      fixture.surface,
      next,
      next.length - 1,
      next.length,
      'deleteContentBackward'
    );
    expect(following.prevented, 'the following block is unaffected').toBe(false);
    await settle();
    expect(fixture.history.getValue()).toBe(`${run.slice(0, -1)}\n\nNext par\n`);
    expect(fixture.onFailure.mock.calls).toEqual([]);
    expect(fixture.onTransferFailure).not.toHaveBeenCalled();
    expect(fixture.runtime().isEditable()).toBe(true);
  } finally {
    fixture.unmount();
    vi.useRealTimers();
  }
});

/**
 * The reported shape: a characterwise Backspace run walks a heading's text down
 * to nothing, and the press after it lands on the emptied row.
 *
 * A marker-only heading row (`## `) is mounted as a plain empty paragraph, so
 * the surface holds neither the marker nor a body: the row exists only in the
 * canonical source. Measured against the live bundle, that press had no owner -
 * the marker-row join owner refuses a row with no content, the emptied-row
 * owner only knows list items, and the empty-paragraph owner needs a block
 * before the row - so the press was a silent no-op and every later press was
 * the same, with the marker run still standing in the source. The row now
 * retires from its own accepted block range: the marker run and one separator
 * beside it, which is the same rule an emptied list item's row uses.
 */
describe('emptied heading row marker retirement', () => {
  it('retires an emptied heading row that is the document\'s only block', () => {
    vi.useFakeTimers();
    // Hand-computed from the fixture text alone: `## ` is source 0..3 and the
    // blank row behind it is 3..5, so both go and the document keeps no bytes.
    const signature = 'emptied-heading-document-only';
    const markdown = '## \n\n';
    const fixture = createFullOwnerFixture({
      editMap: fullOwnerEditMap(signature, [{ endLine: 1, id: 'b0', startLine: 0 }]),
      html: fullOwnerBlock('<p><br></p>', 'b0'),
      markdown,
      signature,
      sourceCaret: 3
    });
    try {
      fixture.surface.focus();
      const emptied = fixture.surface.querySelector('[data-easymde-visual-block-id="b0"]');
      if (!(emptied instanceof HTMLParagraphElement)) {
        throw new Error('emptied-heading-row-missing');
      }
      // The report's caret: on the emptied row itself, at its own offset 0.
      placeCaretInElement(emptied, 0);
      const historyBefore = fixture.history.getHistoryState();
      const before = fullOwnerDispatchBeforeInput(
        fixture.surface,
        { data: null, inputType: 'deleteContentBackward' },
        fullOwnerTargetRange(emptied, 0, 0)
      );
      expect(before.defaultPrevented, 'the emptied row is owned').toBe(true);
      act(() => vi.advanceTimersByTime(80));
      expect(fixture.history.getValue(), 'the marker run and its separator are gone')
        .toBe('');
      expect(fixture.history.getSelection(), 'the caret sits in the empty paragraph')
        .toEqual({ direction: 'none', end: 0, start: 0 });
      expect(fixture.onFailure.mock.calls, 'the press reports no failure').toEqual([]);
      expect(fixture.onTransferFailure.mock.calls).toEqual([]);
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair'),
        'nothing is re-derived or restored'
      ).toBeNull();
      // The existing empty-document state: one paragraph holding its placeholder.
      const paragraph = fixture.surface.querySelector('p');
      expect(fixture.surface.childNodes).toHaveLength(1);
      expect(paragraph?.childNodes).toHaveLength(1);
      expect(paragraph?.firstChild).toBeInstanceOf(HTMLBRElement);
      expect(window.getSelection()?.anchorNode).toBe(paragraph);
      expect(window.getSelection()?.anchorOffset).toBe(0);
      expect(fixture.runtime().isEditable()).toBe(true);
      expect(fixture.history.getHistoryState().undoDepth, 'one history entry')
        .toBe(historyBefore.undoDepth + 1);
      // One press beyond is the documented empty-document no-op: nothing is
      // written, nothing is reported, and the editor keeps editing.
      if (!paragraph) throw new Error('emptied-heading-empty-paragraph-missing');
      const afterRetirement = fixture.history.getHistoryState();
      const beyond = fullOwnerDispatchBeforeInput(
        fixture.surface,
        { data: null, inputType: 'deleteContentBackward' },
        fullOwnerTargetRange(paragraph, 0, 0)
      );
      expect(beyond.defaultPrevented, 'the empty document press is consumed').toBe(true);
      act(() => vi.advanceTimersByTime(80));
      expect(fixture.history.getValue(), 'the empty document is not rewritten').toBe('');
      expect(fixture.history.getSelection()).toEqual({ direction: 'none', end: 0, start: 0 });
      expect(fixture.history.getHistoryState().undoDepth, 'no history entry for a no-op')
        .toBe(afterRetirement.undoDepth);
      expect(fixture.onFailure.mock.calls).toEqual([]);
      expect(fixture.runtime().isEditable()).toBe(true);
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it('joins an emptied heading row into the block before it', () => {
    vi.useFakeTimers();
    // Hand-computed: `段落` is source 0..2, the blank row is 2..3 and `## ` is
    // 3..6, so the press removes 2..6 and leaves `段落\n`.
    const signature = 'emptied-heading-after-paragraph';
    const markdown = '段落\n\n## ';
    const fixture = createFullOwnerFixture({
      editMap: fullOwnerEditMap(signature, [
        { endLine: 1, id: 'b0', startLine: 0 },
        { endLine: 3, id: 'b1', startLine: 2 }
      ]),
      html: fullOwnerParagraphBlock('段落', 'b0') + fullOwnerBlock('<p><br></p>', 'b1'),
      markdown,
      signature,
      sourceCaret: 2
    });
    try {
      fixture.surface.focus();
      const emptied = fixture.surface.querySelectorAll('p')[1];
      const preceding = fixture.surface.querySelectorAll('p')[0]?.firstChild;
      if (!(emptied instanceof HTMLParagraphElement) || !(preceding instanceof Text)) {
        throw new Error('emptied-heading-row-missing');
      }
      placeCaretInElement(emptied, 0);
      const historyBefore = fixture.history.getHistoryState();
      // The browser names a cross-block press by the preceding row's text tail.
      const target = document.createRange();
      target.setStart(preceding, preceding.length);
      target.setEnd(emptied, 0);
      const before = fullOwnerDispatchBeforeInput(
        fixture.surface,
        { data: null, inputType: 'deleteContentBackward' },
        target
      );
      expect(before.defaultPrevented, 'the emptied row is owned').toBe(true);
      act(() => vi.advanceTimersByTime(80));
      expect(fixture.history.getValue(), 'the marker and the separator are gone')
        .toBe('段落\n');
      expect(fixture.history.getSelection(), 'the caret sits at the seam')
        .toEqual({ direction: 'none', end: 3, start: 3 });
      expect(fixture.onFailure.mock.calls, 'the press reports no failure').toEqual([]);
      expect(fixture.onTransferFailure.mock.calls).toEqual([]);
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair'),
        'nothing is re-derived or restored'
      ).toBeNull();
      expect(fixture.history.getHistoryState().undoDepth, 'one history entry')
        .toBe(historyBefore.undoDepth + 1);
      // The row joined into the paragraph: the surface holds that paragraph
      // alone, with the caret at the end of its text.
      const joined = fixture.surface.querySelector<HTMLElement>(
        '[data-easymde-visual-block-id="b0"]'
      );
      expect(joined?.textContent).toBe('段落');
      expect(fixture.surface.querySelectorAll('p')).toHaveLength(1);
      const text = joined?.firstChild;
      if (!(text instanceof Text)) throw new Error('emptied-heading-joined-missing');
      expect(window.getSelection()?.anchorNode).toBe(text);
      expect(window.getSelection()?.anchorOffset).toBe(2);
      // One press beyond: the joined text is ordinary editable text again.
      const beyond = fullOwnerNativeDelete(fixture.surface, text, 1, 2, 'deleteContentBackward');
      expect(beyond.prevented, 'the next press is an ordinary native edit').toBe(false);
      act(() => vi.advanceTimersByTime(80));
      expect(fixture.history.getValue(), 'the next press still acts').toBe('段\n');
      expect(fixture.onFailure.mock.calls, 'no press reports a failure').toEqual([]);
      expect(fixture.runtime().isEditable()).toBe(true);
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it('retires a document-start emptied heading row and leaves the next block first', () => {
    vi.useFakeTimers();
    // The measured browser shape: the emptied row is the document's first block
    // and is still the heading element the accepted render mounted
    // (`<h2><br></h2>`) - the plain empty paragraph only appears after the block
    // rewrite this press must not perform. `## ` is source 0..3 and the blank
    // row is 3..5, so both go and `### 三级标题` becomes the first row.
    const signature = 'emptied-heading-document-start-chain';
    const markdown = '## \n\n### 三级标题\n';
    const fixture = createFullOwnerFixture({
      editMap: fullOwnerEditMap(signature, [
        { endLine: 1, id: 'b0', startLine: 0 },
        { endLine: 3, id: 'b1', startLine: 2 }
      ]),
      html: fullOwnerBlock('<h2><br></h2>', 'b0')
        + fullOwnerBlock('<h3>三级标题</h3>', 'b1'),
      markdown,
      signature,
      sourceCaret: 3
    });
    try {
      fixture.surface.focus();
      const emptied = fixture.surface.querySelector('[data-easymde-visual-block-id="b0"]');
      if (!(emptied instanceof HTMLHeadingElement)) {
        throw new Error('emptied-heading-row-missing');
      }
      // The caret the browser names on an emptied heading: the element itself
      // at its own offset 0.
      placeCaretInElement(emptied, 0);
      const historyBefore = fixture.history.getHistoryState();
      // The keydown must leave this press to the structural owner: the block
      // rewrite it used to perform cannot place a row the renderer never drew,
      // so it left the canonical source unchanged.
      expect(
        pressFullBackspaceKey(fixture.surface),
        'the empty-block shortcut declines the press'
      ).toBe(false);
      expect(emptied.isConnected, 'the row is not rewritten').toBe(true);
      expect(emptied.tagName).toBe('H2');
      // The browser's own beforeinput for that same press.
      const before = fullOwnerDispatchBeforeInput(
        fixture.surface,
        { data: null, inputType: 'deleteContentBackward' },
        fullOwnerTargetRange(emptied, 0, 0)
      );
      expect(before.defaultPrevented, 'the emptied row is owned').toBe(true);
      act(() => vi.advanceTimersByTime(80));
      expect(fixture.history.getValue(), 'the marker row and its separator are gone')
        .toBe('### 三级标题\n');
      expect(fixture.history.getSelection(), 'the caret sits at the next row\'s start')
        .toEqual({ direction: 'none', end: 0, start: 0 });
      expect(fixture.onFailure.mock.calls, 'the press reports no failure').toEqual([]);
      expect(fixture.onTransferFailure.mock.calls).toEqual([]);
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair'),
        'nothing is re-derived or restored'
      ).toBeNull();
      expect(fixture.history.getHistoryState().undoDepth, 'one history entry')
        .toBe(historyBefore.undoDepth + 1);
      const heading = fixture.surface.querySelector('h3');
      expect(fixture.surface.querySelectorAll('p')).toHaveLength(0);
      expect(fixture.surface.querySelector('h2'), 'the emptied row is gone').toBeNull();
      expect(heading?.textContent).toBe('三级标题');
      const headingText = heading?.firstChild;
      if (!(headingText instanceof Text)) {
        throw new Error('emptied-heading-next-row-missing');
      }
      expect(window.getSelection()?.anchorNode).toBe(headingText);
      expect(window.getSelection()?.anchorOffset).toBe(0);
      expect(fixture.runtime().isEditable()).toBe(true);
      // One press beyond: the row now at the document start is a heading with
      // content, whose own boundary is the documented silent no-op - no write,
      // no failure, and the editor keeps editing.
      placeCaretInText(headingText, 0);
      const afterRetirement = fixture.history.getHistoryState();
      const boundary = fullOwnerDispatchBeforeInput(
        fixture.surface,
        { data: null, inputType: 'deleteContentBackward' },
        fullOwnerTargetRange(headingText, 0, 0)
      );
      expect(boundary.defaultPrevented, 'the boundary press is consumed').toBe(true);
      act(() => vi.advanceTimersByTime(80));
      expect(fixture.history.getValue(), 'no byte is written').toBe('### 三级标题\n');
      expect(fixture.history.getHistoryState().undoDepth, 'no history entry for a no-op')
        .toBe(afterRetirement.undoDepth);
      expect(fixture.onFailure.mock.calls).toEqual([]);
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair'),
        'nothing is re-derived or restored'
      ).toBeNull();
      expect(fixture.surface.querySelector('h3'), 'the row is untouched').toBe(heading);
      expect(fixture.runtime().isEditable()).toBe(true);
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it('retires the emptied heading row the surface spells as a plain empty paragraph', () => {
    vi.useFakeTimers();
    // The respelled shape a repaired press leaves behind: the row is a plain
    // `<p><br></p>` and the accepted map no longer names it, so the row is read
    // positionally from the source's first row. Hand-computed from the fixture
    // text alone: `## ` is source 0..3 and the blank row is 3..5.
    const signature = 'emptied-heading-document-start-respelled';
    const markdown = '## \n\n### 三级标题\n';
    const fixture = createFullOwnerFixture({
      editMap: null,
      html: fullOwnerBlock('<p><br></p>', 'b0')
        + fullOwnerBlock('<h3>三级标题</h3>', 'b1'),
      markdown,
      signature,
      sourceCaret: 3
    });
    try {
      fixture.surface.focus();
      const emptied = fixture.surface.querySelector('[data-easymde-visual-block-id="b0"]');
      if (!(emptied instanceof HTMLParagraphElement)) {
        throw new Error('emptied-heading-row-missing');
      }
      // The caret the report measured: a P element at offset 0.
      placeCaretInElement(emptied, 0);
      const historyBefore = fixture.history.getHistoryState();
      const before = fullOwnerDispatchBeforeInput(
        fixture.surface,
        { data: null, inputType: 'deleteContentBackward' },
        fullOwnerTargetRange(emptied, 0, 0)
      );
      expect(before.defaultPrevented, 'the emptied row is owned').toBe(true);
      act(() => vi.advanceTimersByTime(80));
      expect(fixture.history.getValue(), 'the marker row and its separator are gone')
        .toBe('### 三级标题\n');
      expect(fixture.history.getSelection(), 'the caret sits at the next row\'s start')
        .toEqual({ direction: 'none', end: 0, start: 0 });
      expect(fixture.onFailure.mock.calls, 'the press reports no failure').toEqual([]);
      expect(fixture.onTransferFailure.mock.calls).toEqual([]);
      expect(
        fixture.surface.getAttribute('data-easymde-visual-deletion-repair'),
        'nothing is re-derived or restored'
      ).toBeNull();
      expect(fixture.history.getHistoryState().undoDepth, 'one history entry')
        .toBe(historyBefore.undoDepth + 1);
      const heading = fixture.surface.querySelector('h3');
      expect(fixture.surface.querySelectorAll('p')).toHaveLength(0);
      expect(heading?.textContent).toBe('三级标题');
      const headingText = heading?.firstChild;
      if (!(headingText instanceof Text)) {
        throw new Error('emptied-heading-next-row-missing');
      }
      expect(window.getSelection()?.anchorNode).toBe(headingText);
      expect(window.getSelection()?.anchorOffset).toBe(0);
      expect(fixture.runtime().isEditable()).toBe(true);
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });
});

describe('mixed backward and forward delete redo', () => {
  it('keeps the redo path placeable after both delete bursts', () => {
    vi.useFakeTimers();
    const signature = 'mixed-delete-redo';
    const baseTexts = ['Lead paragraph.', 'Target paragraph zeta text.', 'Tail paragraph.'];
    const editMap = fullOwnerEditMap(signature, [
      { endLine: 1, id: 'b0', startLine: 0 },
      { endLine: 3, id: 'b1', startLine: 2 },
      { endLine: 5, id: 'b2', startLine: 4 }
    ]);
    const rendered = (text: string): string => text;
    const documentFor = (texts: readonly string[]): FullOwnerAcceptedDocument => ({
      editMap,
      html: texts
        .map((text, index) => fullOwnerParagraphBlock(rendered(text), `b${index}`))
        .join(''),
      markdown: texts.join('\n\n')
    });
    const fixture = createFullOwnerFixture({
      ...documentFor(baseTexts),
      signature
    });
    try {
      fixture.surface.focus();
      const selector = '[data-easymde-visual-block-id="b1"]';
      const textsOf = (markdown: string): string[] => markdown.split('\n\n');
      const acceptLive = (): void => {
        if (!fixture.runtime().isTransferPending()) return;
        const markdown = fixture.history.getValue();
        fixture.accept({
          editMap,
          html: textsOf(markdown)
            .map((text, index) => fullOwnerParagraphBlock(rendered(text), `b${index}`))
            .join(''),
          markdown
        });
      };
      const texts = baseTexts.slice();
      for (let index = 0; index < 8; index += 1) {
        const text = fullOwnerTextAt(fixture.surface, selector);
        fullOwnerNativeDelete(
          fixture.surface,
          text,
          text.data.length - 1,
          text.data.length,
          'deleteContentBackward'
        );
        texts[1] = fullOwnerTextAt(fixture.surface, selector).data;
        act(() => vi.advanceTimersByTime(80));
        acceptLive();
      }
      placeCaretInText(fullOwnerTextAt(fixture.surface, selector), 0);
      for (let index = 0; index < 8; index += 1) {
        const text = fullOwnerTextAt(fixture.surface, selector);
        fullOwnerNativeDelete(
          fixture.surface,
          text,
          0,
          Math.min(1, text.data.length),
          'deleteContentForward'
        );
        texts[1] = fullOwnerTextAt(fixture.surface, selector).data;
        act(() => vi.advanceTimersByTime(80));
        acceptLive();
      }
      expect(fixture.history.getValue()).toBe(documentFor(texts).markdown);
      const edited = fixture.history.getValue();
      const baseMarkdown = documentFor(baseTexts).markdown;
      const drive = (redo: boolean, limit: number): string[] => {
        let last = fixture.history.getValue();
        let stalled = 0;
        const failures: string[] = [];
        const base = fixture.onFailure.mock.calls.length;
        for (let step = 0; step < limit; step += 1) {
          act(() => fullOwnerHistoryKey(fixture.surface, redo));
          acceptLive();
          failures.push(
            ...fixture.onFailure.mock.calls
              .slice(base + failures.length)
              .map(([code]) => String(code)),
          );
          const next = fixture.history.getValue();
          stalled = next === last ? stalled + 1 : 0;
          last = next;
          if (!redo && next === baseMarkdown) break;
          if (redo && next === edited) break;
          if (stalled > 4) break;
        }
        return failures;
      };
      expect(drive(false, 40)).toEqual([]);
      expect(fixture.history.getValue()).toBe(baseMarkdown);
      const redoFailures = drive(true, 40);
      expect(redoFailures, 'redo path failures').toEqual([]);
      expect(fixture.history.getValue()).toBe(edited);
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });

  it.each([1, 2, 3])('restores the fresh accepted paragraph start after deleting into %i leading spaces', (spaces) => {
    vi.useFakeTimers();
    const signature = 'accepted-leading-delete-redo';
    const prefix = 'Before paragraph alpha one.\n\nBefore paragraph alpha two.\n\n| A |\n| - |\n\n\nAfter paragraph zeta one.\n\n';
    const initialTail = `After${' '.repeat(spaces)}paragraph zeta two.`;
    const markdown = `${prefix}${initialTail}\n`;
    const editMap = fullOwnerEditMap(signature, [
      { id: 'b0', startLine: 0, endLine: 1 },
      { id: 'b1', startLine: 2, endLine: 3 },
      { id: 'b2', startLine: 4, endLine: 6 },
      { id: 'b3', startLine: 8, endLine: 9 },
      { id: 'b4', startLine: 10, endLine: 11 }
    ]);
    const documentFor = (value: string): FullOwnerAcceptedDocument => {
      const tail = value.slice(prefix.length).replace(/\n$/u, '');
      return {
        editMap,
        html: [
          fullOwnerParagraphBlock('Before paragraph alpha one.', 'b0'),
          fullOwnerParagraphBlock('Before paragraph alpha two.', 'b1'),
          fullOwnerTableBlock(['A'], 'b2'),
          fullOwnerParagraphBlock('After paragraph zeta one.', 'b3'),
          fullOwnerParagraphBlock(tail.replace(/^ {1,3}(?![ \t])/u, ''), 'b4')
        ].join('\n'),
        markdown: value
      };
    };
    const fixture = createFullOwnerFixture({ ...documentFor(markdown), signature });
    try {
      const selector = '[data-easymde-visual-block-id="b4"]';
      const acceptLive = (): void => {
        if (fixture.runtime().isTransferPending()) {
          fixture.accept(documentFor(fixture.history.getValue()));
        }
      };
      fixture.surface.focus();
      const firstCell = fixture.surface.querySelector('th');
      if (!firstCell) throw new Error('accepted-leading-first-cell-missing');
      window.getSelection()?.collapse(firstCell, 0);
      for (let press = 0; press < 16; press += 1) {
        act(() => fullOwnerDispatchBeforeInput(fixture.surface, {
          inputType: 'deleteContentBackward', data: null
        }));
      }
      expect(fixture.history.getValue()).toBe(markdown);
      for (let press = 0; press < 8; press += 1) {
        const text = fullOwnerTextAt(fixture.surface, selector);
        act(() => fullOwnerNativeDelete(fixture.surface, text, text.length - 1, text.length, 'deleteContentBackward'));
        act(() => vi.advanceTimersByTime(80));
        acceptLive();
      }
      for (let press = 0; press < 8; press += 1) {
        const text = fullOwnerTextAt(fixture.surface, selector);
        act(() => fullOwnerNativeDelete(fixture.surface, text, 0, 1, 'deleteContentForward'));
        act(() => vi.advanceTimersByTime(80));
        acceptLive();
      }
      const edited = fixture.history.getValue();
      expect(edited).not.toBe(markdown);
      expect(fixture.onFailure).not.toHaveBeenCalled();
      const drive = (redo: boolean, target: string): void => {
        const steps: unknown[] = [];
        for (let step = 0; fixture.history.getValue() !== target && step < 32; step += 1) {
          act(() => fullOwnerHistoryKey(fixture.surface, redo));
          acceptLive();
          steps.push({ length: fixture.history.getValue().length, history: fixture.history.getHistoryState(), pending: fixture.runtime().isTransferPending() });
          expect(fixture.onFailure, `history ${redo ? 'redo' : 'undo'} step ${step}`).not.toHaveBeenCalled();
          expect(fixture.onTransferFailure).not.toHaveBeenCalled();
        }
        expect(fixture.history.getValue().length, JSON.stringify(steps)).toBe(target.length);
        expect(fixture.history.getValue()).toBe(target);
      };
      drive(false, markdown);
      drive(true, edited);
      const text = fullOwnerTextAt(fixture.surface, selector);
      expect(window.getSelection()?.anchorNode === text
        || window.getSelection()?.anchorNode === text.parentElement).toBe(true);
      expect(fixture.surface.querySelectorAll('table')).toHaveLength(1);
      expect(fixture.history.getValue().startsWith(prefix)).toBe(true);
    } finally {
      fixture.unmount();
      vi.useRealTimers();
    }
  });
});

it('binds an empty table context lease to its own source row through delete and Undo', () => {
  vi.useFakeTimers();
  const signature = 'empty-table-context';
  const table = '| |\n| - |';
  const markdown = `Before.\n\n${table}\n\nBetween.\n\n${table}\n\nAfter.`;
  const secondStart = markdown.lastIndexOf(table);
  const initial: FullOwnerAcceptedDocument = {
    markdown,
    editMap: fullOwnerEditMap(signature, [
      { id: 'b0', startLine: 0, endLine: 1 },
      { id: 'b1', startLine: 2, endLine: 4 },
      { id: 'b2', startLine: 5, endLine: 6 },
      { id: 'b3', startLine: 7, endLine: 9 },
      { id: 'b4', startLine: 10, endLine: 11 }
    ]),
    html: [fullOwnerParagraphBlock('Before.', 'b0'), fullOwnerTableBlock(['<br>'], 'b1'),
      fullOwnerParagraphBlock('Between.', 'b2'), fullOwnerTableBlock(['<br>'], 'b3'),
      fullOwnerParagraphBlock('After.', 'b4')].join('\n')
  };
  const fixture = createFullOwnerFixture({ ...initial, signature, sourceCaret: secondStart });
  try {
    fixture.surface.focus();
    const cell = fixture.surface.querySelector('[data-easymde-visual-block-id="b3"] th');
    if (!cell) throw new Error('empty-table-context-cell-missing');
    window.getSelection()?.collapse(cell, 0);
    expect(fixture.runtime().prepareContextMenuDemand()).toBe(true);
    const lease = fixture.runtime().captureContextMenuTarget(cell);
    expect(lease, 'the empty TH must have a source-backed table target').not.toBeNull();
    if (!lease) throw new Error('empty-table-context-lease-missing');
    try {
      const resolved = lease.resolve();
      expect(resolved).toBe(cell.closest('table'));
      expect(fixture.runtime().prepareContextMenuSelection?.(resolved, { x: 4, y: 4 }, 'pointer')).toBe(true);
      const selection = fixture.history.getSelection();
      expect(selection).toEqual({ direction: 'forward', start: secondStart, end: secondStart + table.length });
      expect(tableSelectionAt(markdown, selection)?.kind).toBe('whole-table');
      const edit = editMarkdownTable(markdown, selection.start, { type: 'delete-table' });
      if (!edit?.changes) throw new Error('empty-table-context-delete-missing');
      expect(fixture.runtime().applyCanonicalChange({
        change: { changes: edit.changes, selection: edit.selection, value: edit.value },
        expected: { revision: fullOwnerRevision(fixture), selection, value: markdown }
      })).toBe('handled');
      const afterLine = edit.value.split('\n').indexOf('After.');
      fixture.accept({ markdown: edit.value,
        editMap: fullOwnerEditMap(signature, [
          { id: 'b0', startLine: 0, endLine: 1 }, { id: 'b1', startLine: 2, endLine: 4 },
          { id: 'b2', startLine: 5, endLine: 6 }, { id: 'b4', startLine: afterLine, endLine: afterLine + 1 }
        ]),
        html: [fullOwnerParagraphBlock('Before.', 'b0'), fullOwnerTableBlock(['<br>'], 'b1'),
          fullOwnerParagraphBlock('Between.', 'b2'), fullOwnerParagraphBlock('After.', 'b4')].join('\n')
      });
      expect(fixture.history.getValue()).toBe(edit.value);
      expect(fixture.surface.querySelectorAll('table')).toHaveLength(1);
      act(() => fullOwnerHistoryKey(fixture.surface, false));
      if (fixture.runtime().isTransferPending()) fixture.accept(initial);
      expect(fixture.history.getValue()).toBe(markdown);
      expect(fixture.surface.querySelectorAll('table')).toHaveLength(2);
      expect(fixture.onFailure).not.toHaveBeenCalled();
      expect(fixture.onTransferFailure).not.toHaveBeenCalled();
    } finally { lease.release(); }
  } finally { fixture.unmount(); vi.useRealTimers(); }
});

it.each([false, true])('keeps ordinary native authority but resumes explicit owner transfer=%s', (transfer) => {
  const markdown = 'First.\n\nLast.';
  const signature = 'explicit-owner-transfer';
  const surface = document.createElement('article');
  surface.innerHTML = fullOwnerParagraphBlock('First.', 'b0') + fullOwnerParagraphBlock('Last.', 'b1');
  document.body.append(surface);
  placeCaretInText(fullOwnerTextAt(surface, 'p'), 0);
  const fixture = createFullOwnerFixture({ markdown, surface, signature, sourceCaret: markdown.length,
    html: surface.innerHTML,
    editMap: fullOwnerEditMap(signature, [{ id: 'b0', startLine: 0, endLine: 1 }, { id: 'b1', startLine: 2, endLine: 3 }]),
    prepareHistory: () => {
      surface.focus();
      placeCaretInText(fullOwnerTextAt(surface, 'p'), 0);
    },
    resumeCanonicalSelectionToken: 1, resumeCanonicalSelectionOnOwnerTransfer: transfer
  });
  try {
    const expected = fullOwnerTextAt(surface, 'p', transfer ? 1 : 0);
    const native = window.getSelection();
    expect(native?.anchorNode === expected
      || transfer && native?.anchorNode === expected.parentElement).toBe(true);
    expect(native?.anchorOffset).toBe(transfer
      ? native?.anchorNode === expected ? expected.length : expected.parentElement?.childNodes.length
      : 0);
    expect(fixture.history.getValue()).toBe(markdown);
    expect(fixture.history.getRevision()).toBe(0);
    expect(fixture.onFailure).not.toHaveBeenCalled();
  } finally { fixture.unmount(); surface.remove(); }
});

